<?php
declare(strict_types=1);
define('LCHAT_INTERNAL', true);
require __DIR__ . '/app.php';
$ctx=context(); ensure_features(); $user=require_user($ctx); $uid=(int)$user['id'];
$bot=one('SELECT u.id FROM users u JOIN bot_accounts b ON b.bot_user_id=u.id WHERE LOWER(u.username)=?', ['compilerbot']);
if(!$bot){http_response_code(503);exit('CompilerBot не установлен.');}
$botId=(int)$bot['id'];$key=min($uid,$botId).':'.max($uid,$botId);$chat=one('SELECT id FROM chats WHERE direct_key=?',[$key]);
if(!$chat){$chatId=transaction(function()use($uid,$botId,$key){query('INSERT INTO chats(kind,title,owner_id,direct_key,created_at)VALUES(?,?,?,?,?)',['direct','',$uid,$key,stamp()]);$id=(int)db()->lastInsertId();foreach([$uid,$botId]as$who)query('INSERT INTO members(chat_id,user_id,role,joined_at)VALUES(?,?,?,?)',[$id,$who,'member',stamp()]);return$id;});}else$chatId=(int)$chat['id'];
header('Cache-Control: no-store');
?>
<script>if(globalThis.crypto&&!crypto.randomUUID)crypto.randomUUID=()=>String(Date.now())+Math.random().toString(16).slice(2)+Math.random().toString(16).slice(2);</script>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PyWeb · LChat Compiler</title><style>:root{color-scheme:dark;--bg:#030303;--panel:#090909;--panel2:#0e0e0e;--line:#242424;--text:#f2f2f2;--muted:#777;--green:#7cf0ad}*{box-sizing:border-box}body{margin:0;height:100vh;overflow:hidden;background:#000;color:var(--text);font-family:Inter,system-ui,sans-serif}.app{height:100%;display:grid;grid-template-rows:58px 1fr 25px}.top{display:flex;align-items:center;padding:0 16px;border-bottom:1px solid var(--line);background:#070707}.logo{font-weight:850}.logo span{color:#666}.top a{margin-left:auto;color:#888;text-decoration:none}.work{min-height:0;display:grid;grid-template-columns:210px minmax(0,1fr)}.side{padding:12px;border-right:1px solid var(--line);background:#050505}.side b{display:block;padding:8px;color:#666;font-size:11px;letter-spacing:.12em}.side button{width:100%;padding:10px;margin:2px 0;text-align:left;border:0;border-radius:8px;background:transparent;color:#aaa;cursor:pointer}.side button:hover,.side button.active{background:#121212;color:#fff}.main{min-height:0;display:grid;grid-template-rows:46px minmax(0,1fr) 220px}.toolbar{display:flex;gap:8px;align-items:center;padding:7px 10px;border-bottom:1px solid var(--line);background:#080808}.toolbar input{min-width:0;flex:1}.toolbar button,.toolbar input{height:32px;border:1px solid var(--line);border-radius:8px;background:#111;color:#ddd;padding:0 11px}.toolbar button{cursor:pointer}.toolbar .run{background:#fff;color:#000;font-weight:750}.editor{width:100%;height:100%;resize:none;border:0;outline:0;padding:20px;background:#080808;color:#ddd;font:14px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace}.console{border-top:1px solid var(--line);background:#030303;overflow:auto}.console h3{position:sticky;top:0;margin:0;padding:10px 14px;border-bottom:1px solid var(--line);background:#050505;color:#777;font-size:11px;letter-spacing:.12em}.console pre{margin:0;padding:14px;white-space:pre-wrap;color:#aaa;font:12px/1.55 ui-monospace,monospace}.foot{padding:4px 12px;background:#151515;color:#777;font-size:11px}.modal{position:fixed;inset:0;display:grid;place-items:center;background:#000b}.modal[hidden]{display:none}.box{width:min(460px,calc(100% - 30px));padding:20px;border:1px solid var(--line);border-radius:15px;background:#0b0b0b}.box input{width:100%;height:40px;margin:8px 0;padding:0 10px;background:#050505;border:1px solid var(--line);border-radius:8px;color:#fff}.box button{height:38px;margin-right:8px;padding:0 13px;border:1px solid var(--line);border-radius:8px;background:#171717;color:#fff}@media(max-width:720px){.work{grid-template-columns:1fr}.side{display:none}.main{grid-template-rows:46px minmax(0,1fr) 190px}.toolbar .hide-mobile{display:none}}</style></head><body><main class="app"><header class="top"><div class="logo">LChat <span>/ PyWeb</span></div><a href="index.php">← Мессенджер</a></header><section class="work"><aside class="side"><b>КОМПИЛЯТОР</b><button class="active" data-action="file">● main.py</button><button data-command="/projects">▣ Проекты</button><button data-command="/packages">□ Модули</button><button data-command="/reset">↻ Сбросить env</button><b>САЙТЫ</b><button data-link="sitecreator.php">◇ Site Creator</button></aside><section class="main"><div class="toolbar"><input id="prompt" placeholder="Задача для ИИ…"><button id="ai" class="hide-mobile">ИИ написать</button><button id="fix" class="hide-mobile">ИИ исправить</button><button id="packages" class="hide-mobile">pip</button><button id="run" class="run">▶ Запустить</button></div><textarea id="code" class="editor" spellcheck="false">print("Hello from LChat PyWeb!")</textarea><div class="console"><h3>ТЕРМИНАЛ · @COMPILERBOT</h3><pre id="out">Готов. Код выполняется в изолированном окружении.</pre></div></section></section><footer class="foot">Python · AI: Kilo Auto Free · личные проекты и env</footer></main><div id="pip-modal" class="modal" hidden><div class="box"><b>Установить pip-модули</b><input id="pip-name" placeholder="requests aiogram numpy"><button id="pip-send">Установить</button><button onclick="document.getElementById('pip-modal').hidden=true">Закрыть</button></div></div><script>const CHAT=<?=$chatId?>,CSRF=<?=json_encode($ctx['csrf'])?>,ME=<?=$uid?>;let last=0,busy=false;const $=id=>document.getElementById(id);async function api(action,data={},post=false){const r=await fetch('api.php?action='+encodeURIComponent(action)+(post?'':'&'+new URLSearchParams(data)),post?{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify(data)}:{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Ошибка');return d}async function send(text){if(busy)return;busy=true;$('out').textContent='› Отправлено @compilerbot\nОжидаем результат…';try{await api('message.send',{chat_id:CHAT,body:text,nonce:crypto.randomUUID().replaceAll('-','')},true);await poll(true)}catch(e){$('out').textContent='Ошибка: '+e.message;busy=false}}async function poll(wait=false){for(let i=0;i<(wait?60:1);i++){const d=await api('messages',{chat_id:CHAT,after:last});const items=d.messages||[];for(const m of items){last=Math.max(last,Number(m.id));if(Number(m.user_id)!==ME){$('out').textContent=m.body;busy=false}}if(!wait||!busy)break;await new Promise(r=>setTimeout(r,1500))}}$('run').onclick=()=>send('/run\n'+$('code').value);$('ai').onclick=()=>send('/ai-run '+$('prompt').value);$('fix').onclick=()=>send('/fix\n'+$('code').value);$('packages').onclick=()=>$('pip-modal').hidden=false;$('pip-send').onclick=()=>{document.getElementById('pip-modal').hidden=true;send('/pip '+$('pip-name').value)};document.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>send(b.dataset.command));document.querySelectorAll('[data-link]').forEach(b=>b.onclick=()=>location.href=b.dataset.link);setInterval(()=>{if(!busy)poll()},5000);poll();</script></body></html>
